public sealed class UsersGateway(IDbConnection conn)   // one per table
{
    public User? Find(long id) =>
        conn.QuerySingleOrDefault<User>(
            "SELECT id, name FROM users WHERE id = @id", new { id });

    public int Insert(User u) =>
        conn.Execute("INSERT INTO users (id, name) VALUES (@Id, @Name)", u);
}
